    return this.#run(async()=>{
      const root=await privateDirectory(directory);
      const response=await this.#request('GET','/api/download?'+new URLSearchParams({kind,id}),{scope});
      let handle,temporary,received=0,consumed=false;
      try{
        if(!response.ok){
