  if(manifest.schema!=='stellar-forge.dspace-customer-delivery.v1'||identity(unsigned)!==manifest.sha256||
      !Array.isArray(manifest.files)||manifest.files.length>25000)
    throw fault('DSPACE_DELIVERY_FORMAT','Choose a complete original repository customer delivery.');
  const names=new Set();
  for(const file of manifest.files){
    if(typeof file.path!=='string'||file.path.includes('\\')||file.path.startsWith('/')||
        file.path.split('/').some(p=>!p||p==='.'||p==='..')||names.has(file.path))
      throw fault('DSPACE_DELIVERY_PATH','The original delivery contains an invalid or duplicate file path.');
    names.add(file.path);
