        if(!HASH.test(row.sha256)||!Number.isSafeInteger(row.bytes)||row.bytes<0||row.bytes>MAX_SOURCE_BYTES)
          throw fault('DSPACE_ARCHIVE_FILE','The project contains an invalid original file identity.');
