        if(bytes.length!==row.bytes||hash(bytes)!==row.sha256)throw fault('DSPACE_ARCHIVE_FILE','An original project file failed its digest.');
        target.db.prepare('INSERT INTO blobs VALUES(?,?,?)').run(row.sha256,row.bytes,row.data);
      }
